<?php
namespace Modules\LeaveManagement\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Facades\Auth;
use Modules\LeaveManagement\Support\LeaveAccess;
class LeaveRequest extends Model { protected $table='leave_requests'; protected $fillable=['personnel_id','class_id','class_name','personnel_code','personnel_name','from_date','to_date','leave_type','reason','note','status','created_by','approved_by','approved_at','decision_note','request_scope','object_type','rank','position','enlistment_date','unit_id','unit_name','service_years','base_days','travel_days','extra_days','extra_reasons','total_days','leave_year','locality_id','locality_path','proposed_by_user_id','proposed_by_username','proposed_by_display_name','proposer_email','commander_user_id','commander_name','replacement_personnel_id','replacement_personnel_name','replacement_position','admin_note','decided_by_user_id','decided_by_username','decided_at']; protected $casts=['from_date'=>'date','to_date'=>'date','enlistment_date'=>'date','approved_at'=>'datetime','decided_at'=>'datetime','extra_reasons'=>'array']; protected static function booted(){static::addGlobalScope('leave-unit',function($query){$user=Auth::user();if(LeaveAccess::isScoped($user))$query->where(fn($q)=>$q->whereHas('personnel',fn($p)=>$p->whereIn('unit_id',LeaveAccess::unitIds($user)))->orWhereIn('unit_id',LeaveAccess::unitIds($user)));});static::creating(function(self $request):void{if($request->personnel_id)LeaveAccess::ensurePersonnel((int)$request->personnel_id,Auth::user());});} public function personnel(){return $this->belongsTo(LeavePersonnel::class,'personnel_id');} public function leaveClass(){return $this->belongsTo(LeaveClass::class,'class_id');} public function commander(){return $this->belongsTo(\App\Models\User::class,'commander_user_id');} public function replacement(){return $this->belongsTo(LeavePersonnel::class,'replacement_personnel_id');} }
